function setText(node,value){const text=String(value??"");if(node.textContent!==text)node.textContent=text;}
function nativeAction(action,data={}){if(window.chrome&&window.chrome.webview){window.chrome.webview.postMessage({action,...data});return true;}toast("请在桌面版直播守望中使用此功能。","info");return false;}
let playback=null,playbackTimer=null,playbackGeneration=0,playbackChoice=null;
async function stopPlayback(){clearInterval(playbackTimer);playbackTimer=null;const previous=playback;playback=null;const video=$("liveVideo");video.pause();video.removeAttribute("src");video.load();if(previous)try{await api("/api/playback/"+previous.id+"/close","POST",{});}catch{}}
async function playRoom(id,quality="",protocol=""){
 const generation=++playbackGeneration;playbackChoice={id,quality,protocol};await stopPlayback();if(generation!==playbackGeneration)return;
 setText($("playerName"),roomById(id)?.nickname||"直播画面");setText($("playerStatus"),"正在连接直播源…");if(!$("playerDialog").open)$("playerDialog").showModal();
 try{const session=await api("/api/playback","POST",{room_id:id,quality,protocol});if(generation!==playbackGeneration){await api("/api/playback/"+session.id+"/close","POST",{});return;}playback=session;$("liveVideo").src=session.stream_path;$("liveVideo").play().catch(()=>setText($("playerStatus"),"点击画面的播放按钮开始观看"));playbackTimer=setInterval(async()=>{if(!playback||playback.id!==session.id)return;try{const state=await api("/api/playback/"+session.id+"/status");if(playback?.id!==session.id)return;if(state.state==="failed")setText($("playerStatus"),"直播源连接失败或已过期，请检查状态后重新连接");else if(state.state==="ended")setText($("playerStatus"),"直播源已结束，可重新连接");}catch{}},2000);}catch(e){if(generation===playbackGeneration)setText($("playerStatus"),e.message);}
}
$("playerDialog").addEventListener("close",()=>{++playbackGeneration;stopPlayback();});
$("liveVideo").addEventListener("playing",()=>setText($("playerStatus"),"正在播放 · "+(playback?.quality||"当前直播源")));
$("liveVideo").addEventListener("error",()=>{if(playback)setText($("playerStatus"),"直播源暂不可播放，请检查直播状态或重新连接");});
$("liveVideo").ondblclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else $("liveVideo").requestFullscreen().catch(()=>{});};
$("retryPlayer").onclick=()=>{if(playbackChoice)playRoom(playbackChoice.id,playbackChoice.quality,playbackChoice.protocol);};
window.addEventListener("pagehide",()=>{if(playback)fetch("/api/playback/"+playback.id+"/close",{method:"POST",headers:{"X-LiveWatch-Token":token,"Content-Type":"application/json"},body:"{}",keepalive:true});});
