function streamOptions(){const options=[{key:"origin",label:"原画"},{key:"blue",label:"蓝光"},{key:"ultra",label:"超清"},{key:"high",label:"高清"}];for(const [key,label] of [["standard","标清"],["low","流畅"],["other","其它直播源"],["unknown","当前直播源"]]){const actual=S.streams.find(s=>s.quality===key);if(actual)options.push({key,label:key==="other"?actual.label||label:label});}for(const stream of S.streams)if(!options.some(o=>o.key===stream.quality))options.push({key:stream.quality,label:stream.label||"其它直播源"});return options;}
