function changeSourceQuality(){const available=S.streams.filter(s=>s.quality===$("sourceQuality").value),protocol=$("sourceProtocol"),previous=protocol.value,keys=["hls","flv",...available.map(s=>s.protocol).filter(p=>p!=="hls"&&p!=="flv")];protocol.replaceChildren();for(const key of new Set(keys)){const option=el("option","",key.toUpperCase());option.value=key;protocol.append(option);}protocol.value=available.some(s=>s.protocol===previous)?previous:available.some(s=>s.protocol==="hls")?"hls":available[0]?.protocol||"hls";updateSourceChoice();}
async function openSources(id){
 if(S.loadingRoom)return;S.loadingRoom=true;try{const response=await api("/api/room-source/"+encodeURIComponent(id));const room={...roomById(id),...(response.room||response)};S.sourceRoom=room;S.streams=normalizedStreams(response,room);setText($("sourceName"),room.nickname||room.room_input);setText($("sourcePlatform"),platform(room.platform)+" · "+(liveLabels[room.live_status]||""));$("sourceIssueBtn").classList.toggle("hidden",!room.last_error&&room.live_status!=="error"&&room.record_status!=="failed");$("sourceIssueBtn").title=friendlyRoomReason(room);const sourceAvatar=el("span","avatar");sourceAvatar.append(el("span","avatar-fallback",(room.nickname||platform(room.platform)).slice(0,1)));$("sourceAvatar").replaceChildren(sourceAvatar);if(room.avatar_url||room.has_avatar){const img=el("img","avatar-image");img.alt="";img.src="/api/avatar/"+encodeURIComponent(room.id);img.onload=()=>sourceAvatar.classList.add("avatar-loaded");img.onerror=()=>img.remove();sourceAvatar.append(img);}$("sourceRoomUrl").value=response.room_url||room.room_url||(/^https?:\/\//.test(room.room_input)?room.room_input:room.platform==="douyin"&&room.input_type!=="account"&&/^(?:[0-9]{1,32}|[A-Za-z0-9._-]{2,64})$/.test(room.room_input)?"https://live.douyin.com/"+room.room_input:room.room_input||"");const quality=$("sourceQuality");quality.replaceChildren();for(const option of streamOptions()){const provided=S.streams.some(s=>s.quality===option.key);const element=el("option","",option.label+(provided?"":"（未提供）"));element.value=option.key;quality.append(element);}const preferred=streamOptions().find(option=>S.streams.some(s=>s.quality===option.key));quality.value=preferred?.key||"origin";changeSourceQuality();hideSourceContext();if(!$("sourceDialog").open)$("sourceDialog").showModal();}catch(e){toast(e.message,"error");}finally{S.loadingRoom=false;}
}
async function copyText(value){if(!value){toast("当前没有可复制的直播源。","info");return;}if(window.chrome&&window.chrome.webview){window.chrome.webview.postMessage({action:"copy",text:value});toast("已复制到剪贴板");return;}try{await navigator.clipboard.writeText(value);toast("已复制到剪贴板");}catch{const input=el("textarea","clipboard-fallback");input.value=value;overlayHost().append(input);input.select();const copied=document.execCommand("copy");input.remove();toast(copied?"已复制到剪贴板":"复制失败，请选择链接后按 Ctrl+C",copied?"success":"error");}}
$("sourceIssueBtn").onclick=()=>{if(S.sourceRoom)openRoomStatus(S.sourceRoom.id);};$("sourceQuality").onchange=changeSourceQuality;$("sourceProtocol").onchange=updateSourceChoice;$("sourcePlayBtn").onclick=()=>{if(S.sourceRoom)playRoom(S.sourceRoom.id,$("sourceQuality").value,$("sourceProtocol").value);};$("sourceEditBtn").onclick=()=>{const id=S.sourceRoom?.id;$("sourceDialog").close();if(id)openRoom(id,true);};$("copyRoomUrlBtn").onclick=()=>copyText($("sourceRoomUrl").value);$("copySourceDetailBtn").onclick=()=>copyText($("sourceUrl").dataset.sourceUrl||"");
function hideSourceContext(){hideOverlay($("sourceContextMenu"));S.context=null;}
function showSourceContext(event,id){event.preventDefault();hideSourceContext();const room=id?roomById(id):S.sourceRoom;if(!room)return;S.context={kind:id?"row":"source",id:room.id,returnFocus:event.target};const menu=$("sourceContextMenu"),isRow=Boolean(id);setText($("contextRoomName"),room.nickname||room.room_input||"直播间");setText($("contextCopySource"),isRow?"复制当前最佳直播源":"复制当前直播源");$("contextCopySource").disabled=!isRow&&!$("sourceUrl").dataset.sourceUrl;$("contextViewSource").classList.toggle("hidden",!isRow);$("contextPlayRoom").classList.toggle("hidden",!isRow);showOverlay(menu,event.target.closest("dialog[open]")||overlayHost());const anchor=event.target.getBoundingClientRect(),x=event.clientX||anchor.left+20,y=event.clientY||anchor.top+20;const rect=menu.getBoundingClientRect();menu.style.left=Math.max(8,Math.min(x,window.innerWidth-rect.width-8))+"px";menu.style.top=Math.max(8,Math.min(y,window.innerHeight-rect.height-8))+"px";menu.querySelector("button:not(.hidden):not(:disabled)")?.focus({preventScroll:true});}
async function copyBestSource(id){try{const response=await api("/api/room-source/"+encodeURIComponent(id)),room={...roomById(id),...(response.room||response)},streams=normalizedStreams(response,room),rank=["origin","blue","ultra","high","standard","low","other","unknown"];streams.sort((a,b)=>(rank.includes(a.quality)?rank.indexOf(a.quality):rank.length)-(rank.includes(b.quality)?rank.indexOf(b.quality):rank.length)||Number(b.protocol==="hls")-Number(a.protocol==="hls"));if(!streams.length){toast("当前尚未获取可复制的直播源，请检查开播状态或查看直播源详情。","info");return;}await copyText(streams[0].url);}catch(e){toast(e.message,"error");}}
$("sourceUrl").addEventListener("contextmenu",event=>showSourceContext(event));$("contextCopySource").onclick=()=>{const context=S.context;hideSourceContext();if(context?.kind==="row")copyBestSource(context.id);else copyText($("sourceUrl").dataset.sourceUrl||"");};$("contextViewSource").onclick=()=>{const id=S.context?.id;hideSourceContext();if(id)openSources(id);};$("contextPlayRoom").onclick=()=>{const id=S.context?.id;hideSourceContext();if(id)playRoom(id);};
document.addEventListener("pointerdown",event=>{if(!$("sourceContextMenu").contains(event.target))hideSourceContext();});document.addEventListener("scroll",event=>{if(!$("sourceContextMenu").contains(event.target))hideSourceContext();},true);window.addEventListener("resize",hideSourceContext);$("sourceContextMenu").addEventListener("keydown",event=>{const menu=$("sourceContextMenu");if(event.key==="Escape"){event.preventDefault();event.stopPropagation();const target=S.context?.returnFocus;hideSourceContext();target?.focus?.({preventScroll:true});return;}if(!["ArrowDown","ArrowUp","Home","End"].includes(event.key))return;event.preventDefault();const items=[...menu.querySelectorAll("button:not(.hidden):not(:disabled)")],index=items.indexOf(document.activeElement);items[event.key==="Home"?0:event.key==="End"?items.length-1:(index+(event.key==="ArrowUp"?-1:1)+items.length)%items.length]?.focus();});
for(const dialog of document.querySelectorAll("dialog")){dialog.addEventListener("close",()=>{hideSourceContext();syncToasts();});dialog.addEventListener("toggle",()=>{if(dialog.open)syncToasts();});}$("sourceDialog").addEventListener("close",()=>{$("sourceUrl").value="";$("sourceUrl").dataset.sourceUrl="";S.streams=[];S.sourceRoom=null;});
function bytesToBase64(bytes){let text="";for(let i=0;i<bytes.length;i+=0x8000)text+=String.fromCharCode(...bytes.subarray(i,i+0x8000));return btoa(text);}
$("importBtn").onclick=()=>$("importFile").click();$("importFile").onchange=async()=>{const file=$("importFile").files?.[0];if(!file)return;try{if(file.size>5*1024*1024)throw new Error("文件过大，请使用 5 MB 以内的直播间列表。");const format=file.name.toLowerCase().endsWith(".kd")?"kd":file.name.toLowerCase().endsWith(".csv")?"csv":"";if(!format)throw new Error("请选择 .kd 或 .csv 文件。");$("importBtn").disabled=true;const content_base64=bytesToBase64(new Uint8Array(await file.arrayBuffer()));const result=await api("/api/import","POST",{format,content_base64});showBatchResult(result,"文件导入结果");await refresh();}catch(e){toast(e.message,"error");}finally{$("importFile").value="";$("importBtn").disabled=false;}};
$("exportBtn").onclick=()=>{setText($("exportScope"),S.selected.size?`将导出已选的 ${S.selected.size} 个直播间。`:`将导出全部 ${S.rooms.length} 个直播间。`);$("exportDialog").showModal();};$("exportSaveBtn").onclick=async()=>{const button=$("exportSaveBtn");button.disabled=true;try{const body={format:$("exportFormat").value};if(S.selected.size)body.ids=[...S.selected];const result=await api("/api/export","POST",body);if(typeof result.content_base64!=="string")throw new Error("导出内容无效，请重试。");const binary=atob(result.content_base64),bytes=Uint8Array.from(binary,c=>c.charCodeAt(0)),blob=new Blob([bytes],{type:result.mime||"application/octet-stream"}),url=URL.createObjectURL(blob),link=el("a");link.href=url;link.download=result.filename||("直播间列表."+body.format);document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);$("exportDialog").close();toast("已生成仅含直播间 ID 和主页链接的列表，请选择保存位置。","info");}catch(e){toast(e.message,"error");}finally{button.disabled=false;}};
