function updateDiskStatus(){const disk=S.maintenance.disk||{},free=disk.free_bytes,min=disk.min_free_bytes,known=typeof free==="number"&&Number.isFinite(free),low=disk.recording_allowed===false;const detail=known?`录制磁盘剩余 ${(free/1024**3).toFixed(1)} GiB`:(disk.error||"磁盘空间等待更新");setText($("diskSpaceStatus"),detail+(known&&typeof min==="number"?`，保护阈值 ${(min/1024**3).toFixed(1)} GiB`:""));$("diskSpaceNotice").classList.toggle("hidden",!low);setText($("diskSpaceNotice"),low?(known?`${detail}，低于保护阈值，暂不新增录制。请释放空间或调整监控设置。`:(disk.error||"无法读取磁盘空间，暂不新增录制。")):"");}
